//! Handlers which react to the transitions of a machine.
//!
//! They are the Rust counterpart of the `@OnTransition` methods of the Java
//! implementation. There is no annotation processor in Rust: a handler is a
//! value which implements [`StateMachineInterceptor`](crate::support::state_machine_interceptor::StateMachineInterceptor)
//! and is registered on the machine, or generated by the `#[on_transition]`
//! attribute macro of the macro crate.

/// A handler which runs an action when a transition matches.
pub mod on_transition;
